#!/usr/bin/env bash
# Round 444 claims (SYS-3 stage 2a: IME composition in focus-source, Library search, shortcut-sheet search). One line per claim.
ROOT=${ROOT:-/home/runner/czaba-project/store}
LOOP=${LOOP:-/home/runner/czaba-project/tmp/studio-real-loop}
B=$LOOP/b-round-443
A=app/components/arrangement
cd "$ROOT" || exit 1
echo "K1 head $(git rev-parse HEAD | cut -c1-7) gate443 $(python3 -I -c "import json;a=json.load(open('$LOOP/gates/gate-round-443.json'));print(a['status'],a['commit'][:7])")"
echo "K2 status total $(git status --short --untracked-files=all | wc -l) outside-grants $(git status --short --untracked-files=all | awk '{print $2}' | grep -vxF -f "$B/grants-444.txt" | wc -l)"
sha256sum --quiet -c "$LOOP/b-round-318/protected-sha256.txt" >/dev/null 2>&1; K3RC=$?; echo "K3 protected rc $K3RC granted-protected $(awk '{print $2}' "$LOOP/b-round-318/protected-sha256.txt" | grep -cxF -f "$B/grants-444.txt")"
eq=0; while read p; do cmp -s "$p" "$B/sketch-files/$p" && eq=$((eq+1)); done < "$B/sketch-paths.txt"; echo "K4 tree-equals-sketch $eq/$(wc -l < "$B/sketch-paths.txt")"
if git apply --check -p1 "$B/sketch-444.patch.txt" 2>/dev/null; then echo "K5 sketch-applies yes"; else echo "K5 sketch-applies no"; fi
echo "K6 sketch-sha $(sha256sum "$B/sketch-444.patch.txt" | cut -c1-16) expected $(cut -c1-16 "$B/sketch-444.sha256")"
echo "K7 handlers library-search $(grep -c 'const handleSearchKeyDown' $A/ArrangementLibrary.tsx) sheet-capture $(grep -c "window.addEventListener('keydown', handleSheetKeyDown, true)" $A/ArrangementShortcutSheet.tsx) fs-predicate $(grep -c 'export function isFocusSourceFieldEditingKey' app/lib/focus-source.ts) modal-escape $(grep -c "if (e.key === 'Escape')" app/components/ui/Modal.tsx) search-types $(grep -c 'type="search"' $A/ArrangementLibrary.tsx)/$(grep -c 'type="search"' $A/ArrangementShortcutSheet.tsx)"
echo "K8 ime-guards library $(grep -c 'isImeCompositionKeyDown(event)' $A/ArrangementLibrary.tsx) sheet $(grep -c 'isNativeImeCompositionKeyDown(event)' $A/ArrangementShortcutSheet.tsx) focus-source $(grep -c 'isComposing' app/lib/focus-source.ts) native-helper $(grep -c 'export function isNativeImeCompositionKeyDown' $A/studio-ime-composition.ts)"
echo "K9 rows FT7 $(grep -c "'FT7: " app/lib/__tests__/focus-source-typing.test.tsx) FT8 $(grep -c "'FT8: " app/lib/__tests__/focus-source-typing.test.tsx) FT9 $(grep -c "'FT9: " app/lib/__tests__/focus-source-typing.test.tsx) stage2-file $(test -f app/lib/arrangement/__tests__/ime-composition-stage2-ui.test.tsx && echo present || echo absent)"
echo "K10 modifier-early-return-first $(grep -c "if (event.ctrlKey || event.metaKey || event.altKey || typeof event.key !== 'string') {" app/lib/focus-source.ts)"
echo "K11 doc288 line4 '$(sed -n 4p docs/implementation/2026/quarter-IV/288-sys-3-stage-1-ime-composition.md)' doc289 $(test -f docs/implementation/2026/quarter-IV/289-sys-3-stage-2a-ime-search-fields.md && echo present || echo absent) doc289-line4 '$(sed -n 4p docs/implementation/2026/quarter-IV/289-sys-3-stage-2a-ime-search-fields.md 2>/dev/null)'"
echo "K12 archive $(cmp -s "$LOOP/current-task.md" "$LOOP/tasks/round-443.md" && echo current-equals-443 || echo current-is-new) archive443 $(test -f "$LOOP/tasks/round-443.md" && echo present)"
echo "K13 c443 $(python3 -I -c "import json;c=json.load(open('$LOOP/c-round-443.json'));print(c['taskStatus'],c['browserVerified'],len(c['bugs']))")"
echo "K14 mutants $(wc -l < "$B/mutants/results.jsonl") red $(grep -c '"rc": 1' "$B/mutants/results.jsonl")"
echo "K15 covering $(wc -l < "$B/covering-files.txt") $(sed 's/\x1b\[[0-9;]*m//g' "$B/logs/covering-sketch.log" | grep -E 'Tests ' | grep -oE '[0-9]+ passed' | head -1) $(grep '^rc' "$B/logs/covering-sketch.log")"
echo "K16 browser sketch '$(tail -1 "$B/probe/compare-sketch.txt")' head '$(tail -1 "$B/probe/compare-head.txt")'"
echo "K17 typecheck-sketch '$(tail -1 "$B/logs/typecheck-sketch.log")' biome-scoped '$(tail -1 "$B/logs/biome-scoped-sketch.log")' lint-head '$(grep -oE 'Found [0-9]+ warnings' "$B/logs/lint-head.log")' lint-sketch '$(grep -oE 'Found [0-9]+ warnings' "$B/logs/lint-sketch.log")'"
m=0; for f in claims-444-planning-output.txt claims-444-sketch-output.txt sketch-files/app/lib/focus-source.ts sketch-files/app/components/arrangement/ArrangementLibrary.tsx sketch-files/app/components/arrangement/ArrangementShortcutSheet.tsx sketch-files/app/components/arrangement/studio-ime-composition.ts sketch-files/app/lib/__tests__/focus-source-typing.test.tsx sketch-files/app/lib/arrangement/__tests__/ime-composition-stage2-ui.test.tsx probe/focus-targets.mjs probe/compare-c7.py probe/c7-sketch.json probe/c7-head.json probe/compare-c7-sketch.txt probe/c6-sites-sketch.json probe/c6-held-sketch.json probe/c6-sites-sketch-compare.txt probe/c6-held-sketch-compare.txt probe/native-clear-experiment.mjs probe/native-clear-prevent.json probe/native-clear-control.json probe/altgraph-check.mjs probe/altgraph-check-sketch.json backlog-before-444.json feature-status-before-444.md sketch-444.patch.txt sketch-444.sha256 sketch-paths.txt grants-444.txt sketch-review.md covering-files.txt mutants/run-mutants.py mutants/results.jsonl probe/ime-stage2.mjs probe/compare.py probe/summarize.py probe/head.json probe/sketch.json probe/compare-head.txt probe/compare-sketch.txt logs/precheck-full.log logs/covering-sketch.log logs/typecheck-sketch.log logs/lint-head.log logs/lint-sketch.log logs/biome-scoped-sketch.log logs/inventory-inputs.txt logs/inventory-global-keydown.txt logs/l50-focus-origins.txt logs/probe-server-source-equals-sketch.txt l57-check-c443.txt; do test -f "$B/$f" || { echo "MISSING $f"; m=1; }; done; for id in M1-FS-COMPOSE M2-FS-MODIFIER-ORDER M3-FS-ALTGRAPH M4-LIB-GUARD M5-LIB-REPEAT M6-SHEET-GUARD M7-SHEET-REPEAT M8-NATIVE-229; do test -f "$B/mutants/mutant-$id.log" || { echo "MISSING mutant-$id.log"; m=1; }; done; for f in b-round-318/protected-sha256.txt b-round-440/probe/head-server.sh b-round-441/probe/sketch-server.sh b-round-441/probe/ime-sites.mjs b-round-441/probe/compare.py b-round-442/probe/ime-held.mjs b-round-442/probe/compare-held.py tools/l57-check.py tools/l58-check.py; do test -f "$LOOP/$f" || { echo "MISSING $f"; m=1; }; done; echo "K18 artifacts $([ $m = 0 ] && echo checked || echo MISSING)"
echo "K19 $(cd "$LOOP" && python3 -I tools/l58-check.py current-task.md | tail -1)"
echo "K20 full-suite-sketch $(sed 's/\x1b\[[0-9;]*m//g' "$B/logs/precheck-full.log" | grep -E 'Test Files' | grep -oE '[0-9]+ passed' | head -1) files $(sed 's/\x1b\[[0-9;]*m//g' "$B/logs/precheck-full.log" | grep -E '^ +Tests ' | grep -oE '[0-9]+ passed' | head -1) tests $(grep '^rc' "$B/logs/precheck-full.log")"
echo "K21 probe-server-source $(grep -c '^same ' "$B/logs/probe-server-source-equals-sketch.txt")/4"
echo "K22 inventory inputs $(grep -rnE '<input|<textarea|contentEditable' $A --include=*.tsx | grep -v __tests__ | wc -l) global-keydown $(grep -rn "window.addEventListener('keydown'\|document.addEventListener('keydown'" $A app/contexts/ArrangementContext.tsx app/lib/arrangement --include=*.ts* | grep -v __tests__ | wc -l)"
echo "K23 l50 $(grep -nE 'onPointerDown(Capture)?|onBlur|settleEditor\(|\.focus\(|^\s*\{[^}]*(\.map\(|&&|\?)' $A/ArrangementLibrary.tsx $A/ArrangementShortcutSheet.tsx app/lib/focus-source.ts $A/studio-ime-composition.ts | wc -l)"
echo "K24 mutant-red-rows $(python3 -I -c "import json;print(' '.join(r['id']+'='+'/'.join(r['failedRows']) for r in map(json.loads,open('$B/mutants/results.jsonl'))))")"
echo "K25 modal-importers $(grep -rlzE "import \\{[^}]*\\bModal\\b[^}]*\\} from '~/components/ui(/Modal)?'" app --include=*.tsx | grep -v __tests__ | wc -l) protected $(grep -rlzE "import \\{[^}]*\\bModal\\b[^}]*\\} from '~/components/ui(/Modal)?'" app/components/studio --include=*.tsx | wc -l)"
echo "K26 stage1-on-sketch sites '$(tail -1 "$B/probe/c6-sites-sketch-compare.txt")' held '$(tail -1 "$B/probe/c6-held-sketch-compare.txt")'"
echo "K27 c7 '$(tail -1 "$B/probe/compare-c7-sketch.txt")'"
echo "K28 native-clear $(python3 -I -c "import json,sys;g=lambda f:json.load(open(f));p=g(sys.argv[1]);c=g(sys.argv[2]);print('prevent',p['1440x900:LIB-ESC']['after']['libQuery']+'/'+p['1440x900:SHEET-ESC']['after']['sheetQuery'],'control',repr(c['1440x900:LIB-ESC']['after']['libQuery'])+'/'+repr(c['1440x900:SHEET-ESC']['after']['sheetQuery']))" "$B/probe/native-clear-prevent.json" "$B/probe/native-clear-control.json")"
echo "K29 altgraph $(python3 -I -c "import json,sys;d=json.load(open(sys.argv[1]));print('altGraph-true',sum(1 for k in d['keys'] if k['altGraph']),'of',len(d['keys']),'keydowns')" "$B/probe/altgraph-check-sketch.json")"
echo "K30 workspace-typing-target-returns $(grep -c 'isTypingTarget(event.target)' $A/StudioWorkspace.tsx)"
echo "K31 library-raf-focus $(grep -c 'requestAnimationFrame(() => optionRefs.current.get(sourceId)?.focus())' $A/ArrangementLibrary.tsx)"
echo "K32 pending-status $(grep -rn 'C round [0-9]* pending' docs/implementation | wc -l)"
